import { isFriendshipEvolutionReady } from "./friendship";
import { EVOLUTION_RULES_BY_SPECIES, type EvolutionRule } from "./catalog";

/**
 * Motor de evolução: todas as regras da espécie (ordem do array no catálogo) são testadas;
 * não há “prioridade” que descarte regras posteriores. Vários destinos válidos ao mesmo tempo
 * exigem `chosenToSpeciesId` ou uso de `itemId` que desambigúe.
 */
export type EvolutionContext = {
  speciesId: number;
  level: number;
  friendship?: number;
  itemId?: string | null;
  knownMoves?: string[];
  biomeId?: string | null;
  isDay?: boolean;
  isNight?: boolean;
  /** Crepúsculo UTC (Lycanroc Dusk). */
  isDusk?: boolean;
  /** Dia 06–17h UTC sem crepúsculo (Midday vs Dusk). */
  isDayExcludingDusk?: boolean;
  /** `abilityId` do Pokémon em minúsculas (requisitos como own-tempo). */
  abilityId?: string | null;
  /** Troca entre jogadores (evolução por troca). */
  isTrade?: boolean;
  /** Quando há vários destinos válidos (ex.: Eevee + pedra), o jogador escolhe. */
  chosenToSpeciesId?: number | null;
  /** Stats de batalha persistidos (ex.: Tyrogue). */
  statsAtk?: number;
  statsDefense?: number;
  /** Gênero do Pokémon (M/F); necessário para Burmy, Combee, Salazzle, etc. */
  gender?: string | null;
  /**
   * Item segurado no Pokémon (slug minúsculo, com hífen) — trocas, regras pós-pesca, etc.
   * Não confundir com `itemId` (item de evolução usado a partir da mochila no fluxo de pedra).
   */
  heldItemId?: string | null;
  /**
   * Espécie fisgada imediatamente antes da evolução pós-pesca (validação do servidor; opcional no preview).
   */
  hookedSpeciesId?: number | null;
};

function normalize(v: unknown): string {
  return String(v || "").trim().toLowerCase();
}

/** Normaliza para M/F quando conhecido; senão U (desconhecido). */
export function normalizeEvolutionGender(raw: unknown): "M" | "F" | "U" {
  const s = normalize(raw);
  if (s === "m" || s === "male" || s === "macho") return "M";
  if (s === "f" || s === "female" || s === "femea" || s === "fêmea") return "F";
  return "U";
}

/**
 * Verifica se uma regra casa com o contexto.
 * - `minLevel`: só aplica se for número (inclui 0 → exige nível ≥ 0, sempre verdade; não usamos 0 no catálogo).
 * - `itemId` na regra: o contexto deve trazer o mesmo item (evolução por pedra).
 */
export function ruleMatches(ctx: EvolutionContext, rule: EvolutionRule): boolean {
  if (typeof rule.minLevel === "number") {
    if (Number(ctx.level || 0) < rule.minLevel) return false;
  }

  if (typeof rule.minFriendship === "number") {
    if (Number(ctx.friendship || 0) < rule.minFriendship) return false;
  }

  if (rule.itemId) {
    if (normalize(ctx.itemId) !== normalize(rule.itemId)) return false;
  }

  if (rule.moveId) {
    const moves = Array.isArray(ctx.knownMoves) ? ctx.knownMoves.map(normalize) : [];
    if (!moves.includes(normalize(rule.moveId))) return false;
  }

  if (rule.biomeId && normalize(ctx.biomeId) !== normalize(rule.biomeId)) return false;
  if (rule.requireDay && !ctx.isDay) return false;
  if (rule.requireNight && !ctx.isNight) return false;
  if (rule.requireDayExcludingDusk && !ctx.isDayExcludingDusk) return false;
  if (rule.requireDusk && !ctx.isDusk) return false;
  if (rule.requireAbility) {
    if (normalize(ctx.abilityId) !== normalize(rule.requireAbility)) return false;
  }

  if (rule.tradeOnly && !ctx.isTrade) return false;

  if (rule.forbidPokemonHeldItemId) {
    if (normalize(ctx.heldItemId) === normalize(rule.forbidPokemonHeldItemId)) return false;
  }
  if (rule.requirePokemonHeldItemId) {
    if (normalize(ctx.heldItemId) !== normalize(rule.requirePokemonHeldItemId)) return false;
  }
  if (typeof rule.requiresHookedSpeciesId === "number" && Number.isFinite(rule.requiresHookedSpeciesId)) {
    if (Math.trunc(Number(ctx.hookedSpeciesId ?? 0)) !== Math.trunc(rule.requiresHookedSpeciesId)) return false;
  }

  if (rule.compareAtkToDef) {
    const atk = Math.trunc(Number(ctx.statsAtk ?? 0));
    const def = Math.trunc(Number(ctx.statsDefense ?? 0));
    if (atk <= 0 || def <= 0) return false;
    if (rule.compareAtkToDef === "gt" && !(atk > def)) return false;
    if (rule.compareAtkToDef === "lt" && !(atk < def)) return false;
    if (rule.compareAtkToDef === "eq" && !(atk === def)) return false;
  }

  if (rule.requireGender) {
    const g = normalizeEvolutionGender(ctx.gender);
    if (g === "U") return false;
    if (rule.requireGender !== g) return false;
  }

  return true;
}

export type EvolutionRulesMap = Record<number, EvolutionRule[]>;

function cloneRulesMap(base: EvolutionRulesMap): EvolutionRulesMap {
  const out: EvolutionRulesMap = {};
  for (const k of Object.keys(base)) {
    const id = Number(k);
    out[id] = [...(base[id] ?? [])];
  }
  return out;
}

/** Mescla regras estáticas com extras (ex.: Firestore `evolutionConfigRules`). */
export function mergeEvolutionRulesMaps(
  staticMap: EvolutionRulesMap,
  extras: { fromSpeciesId: number; rule: EvolutionRule }[]
): EvolutionRulesMap {
  const out = cloneRulesMap(staticMap);
  for (const { fromSpeciesId, rule } of extras) {
    const sid = Math.max(1, Math.trunc(Number(fromSpeciesId)));
    if (!out[sid]) out[sid] = [];
    out[sid] = [...out[sid], rule];
  }
  return out;
}

export function listMatchingEvolutionTargets(
  ctx: EvolutionContext,
  rulesBySpecies: EvolutionRulesMap = EVOLUTION_RULES_BY_SPECIES
): number[] {
  const speciesId = Math.max(1, Number(ctx.speciesId || 1));
  const ruleList = rulesBySpecies[speciesId] ?? [];
  const out: number[] = [];
  for (const rule of ruleList) {
    if (ruleMatches(ctx, rule)) out.push(rule.toSpeciesId);
  }
  return [...new Set(out)];
}

/**
 * Alvos que podem ser oferecidos após subir de nível (sem item, sem trade-only).
 * Usado para pendência / modal de confirmação.
 */
export function listLevelUpEvolutionOfferTargets(
  ctx: EvolutionContext,
  rulesBySpecies: EvolutionRulesMap = EVOLUTION_RULES_BY_SPECIES
): number[] {
  const speciesId = Math.max(1, Number(ctx.speciesId || 1));
  const ruleList = rulesBySpecies[speciesId] ?? [];
  const out: number[] = [];
  for (const rule of ruleList) {
    if (rule.itemId) continue;
    if (rule.tradeOnly) continue;
    if (typeof rule.requiresHookedSpeciesId === "number" && Number.isFinite(rule.requiresHookedSpeciesId)) continue;
    if (ruleMatches(ctx, rule)) out.push(rule.toSpeciesId);
  }
  return [...new Set(out)];
}

/**
 * Resolve um único alvo. Ambíguo sem `chosenToSpeciesId` → null (UI deve pedir escolha).
 */
export function resolveEvolutionTarget(
  ctx: EvolutionContext,
  rulesBySpecies: EvolutionRulesMap = EVOLUTION_RULES_BY_SPECIES
): number | null {
  const matches = listMatchingEvolutionTargets(ctx, rulesBySpecies);
  if (matches.length === 0) return null;
  if (matches.length === 1) return matches[0];

  const chosen = ctx.chosenToSpeciesId != null ? Math.max(1, Math.trunc(Number(ctx.chosenToSpeciesId))) : null;
  if (chosen != null && matches.includes(chosen)) return chosen;

  return null;
}

export function canEvolve(
  ctx: EvolutionContext,
  rulesBySpecies: EvolutionRulesMap = EVOLUTION_RULES_BY_SPECIES
): boolean {
  return resolveEvolutionTarget(ctx, rulesBySpecies) != null;
}

/**
 * Mensagens de bloqueio para UI / CF.
 * Ordem: ramo ambíguo → bioma → golpe → amizade → dia/noite → nível → item → genérico.
 * Preview e execução usam o mesmo motor; mensagens refletem o mesmo `EvolutionContext`.
 */
export function describeEvolutionBlockReason(
  ctx: EvolutionContext,
  rulesBySpecies: EvolutionRulesMap = EVOLUTION_RULES_BY_SPECIES
): string {
  const speciesId = Math.max(1, Number(ctx.speciesId || 1));
  const ruleList = rulesBySpecies[speciesId] ?? [];
  if (ruleList.length === 0) return "Esta especie nao possui evolucao configurada no jogo.";

  const matches = listMatchingEvolutionTargets(ctx, rulesBySpecies);
  if (matches.length > 1 && (ctx.chosenToSpeciesId == null || !matches.includes(Number(ctx.chosenToSpeciesId)))) {
    return "Varias evolucoes sao possiveis. Escolha o destino (ou use o item correto).";
  }

  for (const rule of ruleList) {
    if (!rule.biomeId) continue;
    if (ruleMatches(ctx, rule)) continue;
    const patched = { ...ctx, biomeId: normalize(rule.biomeId) };
    if (ruleMatches(patched, rule)) {
      return "Esta evolucao exige um bioma especifico. Viaje ate o bioma correto (usa-se o bioma salvo do personagem, igual ao servidor).";
    }
  }

  for (const rule of ruleList) {
    if (!rule.moveId) continue;
    if (ruleMatches(ctx, rule)) continue;
    const patched = { ...ctx, knownMoves: [...(ctx.knownMoves || []), rule.moveId] };
    if (ruleMatches(patched, rule)) {
      return "Esta evolucao exige que o Pokemon conheca um golpe especifico.";
    }
  }

  /**
   * Só sugerir amizade se **alguma** regra com `minFriendship` estiver bloqueada *só* por amizade.
   * Antes: qualquer espécie com um ramo de amizade (ex. Eevee) fazia o jogador de Piloswine/Primeape
   * (só exigem golpe) ver a mensagem de amizade incorretamente.
   */
  const blockedOnlyByLowFriendship = ruleList.some((r) => {
    if (typeof r.minFriendship !== "number") return false;
    if (ruleMatches(ctx, r)) return false;
    const w: EvolutionContext = { ...ctx, friendship: 255, knownMoves: ctx.knownMoves || [] };
    return ruleMatches(w, r);
  });
  if (blockedOnlyByLowFriendship && !isFriendshipEvolutionReady(ctx.friendship)) {
    return "Aumente a amizade (batalhas, nivel, cuidados) para evoluir.";
  }

  const needsDay = ruleList.some((r) => r.requireDay);
  const needsNight = ruleList.some((r) => r.requireNight);
  const needsDayEx = ruleList.some((r) => r.requireDayExcludingDusk);
  const needsDusk = ruleList.some((r) => r.requireDusk);
  if (needsDay && !ctx.isDay) {
    return "Esta evolucao so ocorre de dia (UTC 6h-18h; mesmo criterio no app e no servidor).";
  }
  if (needsNight && !ctx.isNight) {
    return "Esta evolucao so ocorre a noite (UTC; mesmo criterio no app e no servidor).";
  }
  if (needsDayEx && !ctx.isDayExcludingDusk) {
    return "Esta evolucao so ocorre de dia fora do crepusculo (UTC 6h-17h). O crepusculo (17h-18h) usa outra forma.";
  }
  if (needsDusk && !ctx.isDusk) {
    return "Esta evolucao so ocorre no crepusculo (UTC 17h-18h).";
  }

  const needsGender = ruleList.some((r) => r.requireGender);
  if (needsGender && normalizeEvolutionGender(ctx.gender) === "U") {
    return "Esta evolucao exige genero especifico; o Pokemon precisa ter genero M ou F registrado.";
  }

  const needsAbility = ruleList.some((r) => r.requireAbility);
  if (needsAbility) {
    const req = ruleList.map((r) => r.requireAbility).find(Boolean);
    if (req && normalize(ctx.abilityId) !== normalize(req)) {
      return "Esta evolucao exige uma habilidade especifica no Pokemon (ex.: Own Tempo para Lycanroc Dusk).";
    }
  }

  const levelMins = ruleList.filter((r) => typeof r.minLevel === "number").map((r) => r.minLevel!);
  if (levelMins.length > 0) {
    const minL = Math.min(...levelMins);
    if (Number(ctx.level || 0) < minL) {
      return `Nivel minimo entre as regras desta especie: ${minL}.`;
    }
  }

  const allRulesNeedItem = ruleList.length > 0 && ruleList.every((r) => !!r.itemId);
  if (allRulesNeedItem && !normalize(ctx.itemId)) {
    return "Todas as evolucoes desta especie exigem item. Use na Mochila (aba Itens) neste Pokemon.";
  }

  if (ruleList.some((r) => r.itemId) && !normalize(ctx.itemId)) {
    return "Alguns caminhos exigem item de evolucao na Mochila; ajuste nivel, amizade, horario ou bioma para os demais.";
  }

  const withTrade = { ...ctx, isTrade: true };
  const tradeMatches = listMatchingEvolutionTargets(withTrade, rulesBySpecies);
  const nowMatches = listMatchingEvolutionTargets(ctx, rulesBySpecies);
  if (tradeMatches.length > 0 && nowMatches.length === 0 && ruleList.some((r) => r.tradeOnly)) {
    return "Esta especie so evolui ao ser recebida em uma troca com outro jogador (nao da para evoluir so na Mochila).";
  }

  if (ruleList.some((r) => r.tradeOnly && r.itemId) && ctx.isTrade && !normalize(ctx.itemId)) {
    return "Esta evolucao por troca exige um item segurado no Pokemon (Mochila > Itens > equipar na BOX ou no time) antes da troca.";
  }

  return "Ainda nao e possivel evoluir com as condicoes atuais.";
}
