import speciesData from "../data/pokemonSpecies.json";

export type StatKey = "hp" | "atk" | "def" | "spa" | "spd" | "spe";

function speciesList(): any[] {
  const raw = speciesData as unknown;
  return Array.isArray(raw) ? raw : Object.values(raw as Record<string, unknown>);
}

export function getSpeciesEntry(speciesId: number): any | null {
  const list = speciesList();
  return (
    list.find((p) => Number(p?.id) === Number(speciesId)) ||
    list.find((p) => Number(p?.speciesId) === Number(speciesId)) ||
    null
  );
}

export function getSpeciesName(speciesId: number): string {
  const e = getSpeciesEntry(speciesId);
  const n = String(e?.name ?? e?.speciesName ?? "").trim();
  return n || `#${speciesId}`;
}

export function resolveBaseStats(speciesId: number): Record<StatKey, number> | null {
  const found = getSpeciesEntry(speciesId);
  if (!found) return null;

  if (found.baseStats) {
    return {
      hp: Number(found.baseStats.hp ?? 0),
      atk: Number(found.baseStats.atk ?? 0),
      def: Number(found.baseStats.def ?? 0),
      spa: Number(found.baseStats.spa ?? 0),
      spd: Number(found.baseStats.spd ?? 0),
      spe: Number(found.baseStats.spe ?? 0),
    };
  }

  if (found.stats) {
    const s = found.stats;
    return {
      hp: Number(s.hp ?? 0),
      atk: Number(s.atk ?? s.attack ?? 0),
      def: Number(s.def ?? s.defense ?? 0),
      spa: Number(s.spa ?? s.specialAttack ?? 0),
      spd: Number(s.spd ?? s.specialDefense ?? 0),
      spe: Number(s.spe ?? s.speed ?? 0),
    };
  }

  return null;
}

export function getSpeciesAbilities(speciesId: number): string[] {
  const e = getSpeciesEntry(speciesId);
  const abilitiesRaw = e?.abilities;
  if (!Array.isArray(abilitiesRaw)) return [];
  return abilitiesRaw
    .map((a: any) => String(a?.abilityId ?? a?.id ?? a?.name ?? "").trim())
    .filter(Boolean);
}

export function getAbilitySlotIndex(speciesId: number, abilityId: string): number {
  const e = getSpeciesEntry(speciesId);
  const abilitiesRaw = e?.abilities;
  if (!Array.isArray(abilitiesRaw)) return -1;
  for (let i = 0; i < abilitiesRaw.length; i++) {
    const a = abilitiesRaw[i];
    const id = String(a?.abilityId ?? a?.id ?? a?.name ?? "");
    if (id === abilityId) return i;
  }
  return -1;
}
