/**
 * Fase dia/noite usada em evoluções (ex.: Eevee → Espeon/Umbreon).
 * Baseada em UTC para consistência entre cliente e Cloud Function.
 * Dia: 06:00–18:00 UTC; noite: restante.
 */
export function resolveDayNightPhaseUtc(utcTimestampMs: number): { isDay: boolean; isNight: boolean } {
  const h = new Date(utcTimestampMs).getUTCHours();
  const isDay = h >= 6 && h < 18;
  return { isDay, isNight: !isDay };
}

/**
 * Janela "crepúsculo" para evoluções especiais (ex.: Lycanroc Dusk).
 * UTC: 17:00 ≤ t < 18:00 (1 hora). Ajuste único no código se o produto mudar o recorte.
 */
export function resolveDuskPhaseUtc(utcTimestampMs: number): boolean {
  const h = new Date(utcTimestampMs).getUTCHours();
  return h >= 17 && h < 18;
}

/** Dia "estrito" sem o crepúsculo: 06:00–17:00 UTC (Midday Lycanroc vs Dusk). */
export function resolveDayExcludingDuskUtc(utcTimestampMs: number): boolean {
  const h = new Date(utcTimestampMs).getUTCHours();
  return h >= 6 && h < 17;
}
