function collectEvolutionItemIds(map: Record<number, EvolutionRule[]>): Set<string> {
  const s = new Set<string>();
  for (const arr of Object.values(map)) {
    for (const r of arr) {
      if (r.itemId) s.add(String(r.itemId).trim().toLowerCase());
    }
  }
  return s;
}

export const EVOLUTION_RULES_BY_SPECIES: Record<number, EvolutionRule[]> = rules;

/** Itens que aparecem em alguma regra de evolução (pedras, prism scale, etc.). */
export const EVOLUTION_TRIGGER_ITEM_IDS: ReadonlySet<string> = collectEvolutionItemIds(rules);

export function isEvolutionTriggerItemId(itemId: string): boolean {
  return EVOLUTION_TRIGGER_ITEM_IDS.has(String(itemId || "").trim().toLowerCase());
}

/** Inclui itens definidos só em regras mescladas (Firestore). */
export function isEvolutionTriggerItemIdMerged(itemId: string, merged: Record<number, EvolutionRule[]>): boolean {
  if (isEvolutionTriggerItemId(itemId)) return true;
  const n = String(itemId || "").trim().toLowerCase();
  for (const arr of Object.values(merged)) {
    for (const r of arr) {
      if (r.itemId && String(r.itemId).trim().toLowerCase() === n) return true;
    }
  }
  return false;
}
