import type { EvolutionRule } from "./catalog";

/** Documento Firestore `evolutionConfigRules/{id}` (campos flexíveis). */
export type EvolutionConfigRuleDoc = {
  enabled?: boolean;
  fromSpeciesId?: number;
  toSpeciesId?: number;
  biomeId?: string | null;
  minLevel?: number | null;
  minFriendship?: number | null;
  itemId?: string | null;
  moveId?: string | null;
  requireDay?: boolean;
  requireNight?: boolean;
  tradeOnly?: boolean;
  compareAtkToDef?: "gt" | "lt" | "eq";
  requireGender?: "M" | "F";
};

function normStr(v: unknown): string | undefined {
  if (v == null) return undefined;
  const s = String(v).trim().toLowerCase();
  return s || undefined;
}

/**
 * Converte um documento do admin em regra do motor. Retorna null se inválido ou desabilitado.
 */
export function evolutionRuleFromConfigDoc(data: Record<string, unknown>): {
  fromSpeciesId: number;
  rule: EvolutionRule;
} | null {
  if (data.enabled === false) return null;
  const fromSpeciesId = Math.max(1, Math.trunc(Number(data.fromSpeciesId ?? 0)));
  const toSpeciesId = Math.max(1, Math.trunc(Number(data.toSpeciesId ?? 0)));
  if (!fromSpeciesId || !toSpeciesId) return null;

  const rule: EvolutionRule = { toSpeciesId };

  const biome = normStr(data.biomeId);
  if (biome) rule.biomeId = biome;

  if (typeof data.minLevel === "number" && Number.isFinite(data.minLevel)) {
    rule.minLevel = Math.max(0, Math.trunc(data.minLevel));
  }
  if (typeof data.minFriendship === "number" && Number.isFinite(data.minFriendship)) {
    rule.minFriendship = Math.max(0, Math.trunc(data.minFriendship));
  }

  const itemId = normStr(data.itemId);
  if (itemId) rule.itemId = itemId;

  const moveId = normStr(data.moveId);
  if (moveId) rule.moveId = moveId;

  if (data.requireDay === true) rule.requireDay = true;
  if (data.requireNight === true) rule.requireNight = true;
  if (data.tradeOnly === true) rule.tradeOnly = true;

  const cad = normStr(data.compareAtkToDef);
  if (cad === "gt" || cad === "lt" || cad === "eq") rule.compareAtkToDef = cad;

  const rg = normStr(data.requireGender);
  if (rg === "m" || rg === "male") rule.requireGender = "M";
  if (rg === "f" || rg === "female") rule.requireGender = "F";

  return { fromSpeciesId, rule };
}

export function parseEvolutionConfigDocuments(
  docs: { id: string; data: Record<string, unknown> }[]
): { fromSpeciesId: number; rule: EvolutionRule }[] {
  const out: { fromSpeciesId: number; rule: EvolutionRule }[] = [];
  for (const d of docs) {
    const parsed = evolutionRuleFromConfigDoc(d.data);
    if (parsed) out.push(parsed);
  }
  return out;
}
