import { FRIENDSHIP_DEFAULT } from "./friendship";
import { resolveDayNightPhaseUtc, resolveDayExcludingDuskUtc, resolveDuskPhaseUtc } from "./dayNight";
import type { EvolutionContext } from "./engine";

export type BuildEvolutionContextArgs = {
  speciesId: number;
  level: number;
  friendship?: number;
  knownMoves?: string[];
  biomeId?: string | null | undefined;
  itemId?: string | null | undefined;
  chosenToSpeciesId?: number | null | undefined;
  /** Evolução exclusiva de troca (validação servidor / pós-troca). */
  isTrade?: boolean;
  statsAtk?: number;
  statsDefense?: number;
  /** Gênero (M/F) do Pokémon para regras `requireGender`. */
  gender?: string | null;
  /** Habilidade atual do Pokémon (ex.: own-tempo para Lycanroc Dusk). */
  abilityId?: string | null;
  /** Item que o Pokémon está segurando (slug minúsculo, com hífen). */
  heldItemId?: string | null | undefined;
  /** Pós-pesca: espécie do gancho, para evolução imediata (ex.: Shellder + King's Rock). */
  hookedSpeciesId?: number | null | undefined;
  /**
   * Golpes do histórico / relearn no Firestore. Unidos a `knownMoves` para regras `moveId`
   * (jogos oficiais exigem slot ativo; aqui alinhamos expectativa de jogador + tutoria).
   */
  moveHistory?: string[];
  relearnableMoves?: string[];
  /**
   * Timestamp UTC em ms para dia/noite (mesmo critério no app e na Cloud Function).
   * Padrão: `Date.now()` no chamador.
   */
  utcTimestampMs: number;
};

/** Mesma normalização usada no motor e na CF (bioma do personagem / regras). */
export function normalizeBiomeId(raw: string | null | undefined): string | null {
  if (raw == null) return null;
  const s = String(raw).trim().toLowerCase();
  return s || null;
}

/** IDs de golpe normalizados (slug), única lista para o motor. */
function mergeKnownMoveIdsForEvolutionCheck(args: BuildEvolutionContextArgs): string[] {
  const out = new Set<string>();
  const addList = (list: unknown) => {
    if (!Array.isArray(list)) return;
    for (const x of list) {
      const s = String(x || "").trim().toLowerCase();
      if (s) out.add(s);
    }
  };
  addList(args.knownMoves);
  addList(args.moveHistory);
  addList(args.relearnableMoves);
  return Array.from(out);
}

/**
 * Constrói o contexto de evolução de forma única para preview (cliente) e validação (servidor).
 * O servidor deve passar `biomeId` já resolvido do Firestore (`biomeAtualId`), nunca confiar no client para isso na CF.
 */
export function buildEvolutionContext(args: BuildEvolutionContextArgs): EvolutionContext {
  const { isDay, isNight } = resolveDayNightPhaseUtc(args.utcTimestampMs);
  const isDusk = resolveDuskPhaseUtc(args.utcTimestampMs);
  const isDayExcludingDusk = resolveDayExcludingDuskUtc(args.utcTimestampMs);
  const itemRaw = args.itemId;
  const itemId =
    itemRaw != null && String(itemRaw).trim() !== "" ? String(itemRaw).trim().toLowerCase() : null;
  const heldRaw = args.heldItemId;
  const heldItemId =
    heldRaw != null && String(heldRaw).trim() !== "" ? String(heldRaw).trim().toLowerCase().replace(/_/g, "-") : null;
  const hookedSpeciesId =
    args.hookedSpeciesId != null && Number.isFinite(Number(args.hookedSpeciesId))
      ? Math.max(0, Math.trunc(Number(args.hookedSpeciesId)))
      : null;
  const chosen =
    args.chosenToSpeciesId != null && Number.isFinite(Number(args.chosenToSpeciesId))
      ? Math.max(1, Math.trunc(Number(args.chosenToSpeciesId)))
      : null;

  return {
    speciesId: Math.max(1, Math.trunc(Number(args.speciesId))),
    level: Math.max(1, Math.trunc(Number(args.level))),
    friendship: Number(args.friendship ?? FRIENDSHIP_DEFAULT),
    knownMoves: mergeKnownMoveIdsForEvolutionCheck(args),
    biomeId: normalizeBiomeId(args.biomeId),
    itemId,
    isDay,
    isNight,
    isDusk,
    isDayExcludingDusk,
    abilityId:
      args.abilityId != null && String(args.abilityId).trim() !== ""
        ? String(args.abilityId).trim().toLowerCase()
        : null,
    chosenToSpeciesId: chosen,
    isTrade: Boolean(args.isTrade),
    heldItemId,
    hookedSpeciesId: hookedSpeciesId != null && hookedSpeciesId > 0 ? hookedSpeciesId : null,
    statsAtk:
      args.statsAtk != null && Number.isFinite(Number(args.statsAtk)) ? Math.trunc(Number(args.statsAtk)) : undefined,
    statsDefense:
      args.statsDefense != null && Number.isFinite(Number(args.statsDefense))
        ? Math.trunc(Number(args.statsDefense))
        : undefined,
    gender: args.gender != null && String(args.gender).trim() !== "" ? String(args.gender).trim() : undefined,
  };
}
