import type { StatKey } from "./species";

export type { StatKey };

const NATURE_EFFECTS: Record<string, { up?: Exclude<StatKey, "hp">; down?: Exclude<StatKey, "hp"> }> = {
  Hardy: {},
  Lonely: { up: "atk", down: "def" },
  Brave: { up: "atk", down: "spe" },
  Adamant: { up: "atk", down: "spa" },
  Naughty: { up: "atk", down: "spd" },
  Bold: { up: "def", down: "atk" },
  Docile: {},
  Relaxed: { up: "def", down: "spe" },
  Impish: { up: "def", down: "spa" },
  Lax: { up: "def", down: "spd" },
  Timid: { up: "spe", down: "atk" },
  Hasty: { up: "spe", down: "def" },
  Serious: {},
  Jolly: { up: "spe", down: "spa" },
  Naive: { up: "spe", down: "spd" },
  Modest: { up: "spa", down: "atk" },
  Mild: { up: "spa", down: "def" },
  Quiet: { up: "spa", down: "spe" },
  Bashful: {},
  Rash: { up: "spa", down: "spd" },
  Calm: { up: "spd", down: "atk" },
  Gentle: { up: "spd", down: "def" },
  Sassy: { up: "spd", down: "spe" },
  Careful: { up: "spd", down: "spa" },
  Quirky: {},
};

function natureMultiplier(natureName: string | undefined, stat: StatKey): number {
  const n = natureName || "Docile";
  const fx = NATURE_EFFECTS[n] || {};
  if (fx.up === stat) return 1.1;
  if (fx.down === stat) return 0.9;
  return 1.0;
}

export function calcRealStats(args: {
  level: number;
  nature?: string;
  base: Record<StatKey, number>;
  ivs?: Partial<Record<StatKey, number>>;
  evs?: Partial<Record<StatKey, number>>;
}): Record<StatKey, number> {
  const level = Math.max(1, Number(args.level || 1));
  const ivs = args.ivs || {};
  const evs = args.evs || {};

  function iv(stat: StatKey) {
    return Math.max(0, Number(ivs[stat] ?? 0));
  }
  function ev(stat: StatKey) {
    return Math.max(0, Number(evs[stat] ?? 0));
  }

  const base = args.base;

  const hp =
    Math.floor(((2 * base.hp + iv("hp") + Math.floor(ev("hp") / 4)) * level) / 100) + level + 10;

  const other = (stat: Exclude<StatKey, "hp">) => {
    const raw =
      Math.floor(((2 * base[stat] + iv(stat) + Math.floor(ev(stat) / 4)) * level) / 100) + 5;
    return Math.floor(raw * natureMultiplier(args.nature, stat));
  };

  return {
    hp,
    atk: other("atk"),
    def: other("def"),
    spa: other("spa"),
    spd: other("spd"),
    spe: other("spe"),
  };
}
